def matches_pattern(pattern, query_string, good_letters):
    bad_letters = ''.join(chr(ord('a') + i) for i in range(26) if chr(ord('a') + i) not in good_letters)
    bad_letters_set = set(bad_letters)

    def match_segment(p, s):
        if len(p) != len(s):
            return False
        for pc, sc in zip(p, s):
            if pc != '?' and pc != sc:
                return False
        return True

    if '*' in pattern:
        star_index = pattern.index('*')
        prefix = pattern[:star_index]
        suffix = pattern[star_index + 1:]
        if len(prefix) + len(suffix) > len(query_string):
            return False
        if not match_segment(prefix, query_string[:len(prefix)]):
            return False
        if not match_segment(suffix, query_string[-len(suffix):]):
            return False
        middle = query_string[len(prefix):-len(suffix)] if suffix else query_string[len(prefix):]
        return all(c in bad_letters_set for c in middle)
    else:
        return match_segment(pattern, query_string)

